#!/usr/bin/env python3
"""Build a useful HTML-first home from the same verified snapshot as search pages."""
import csv
import html
import io
import json
import sys
from pathlib import Path
from datetime import date

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path: sys.path.insert(0,str(ROOT))
PUB = ROOT / 'public'
SITE = 'https://flscratchstats.com'
PRICES = [1, 2, 3, 5, 10, 20, 30, 50]

def esc(value): return html.escape(str(value if value is not None else ''), quote=True)
def money(value):
    if value is None: return '—'
    if value >= 1e9: return '$' + f'{value / 1e9:,.2f}'.rstrip('0').rstrip('.') + 'B'
    if value >= 1e6: return '$' + f'{value / 1e6:,.1f}'.rstrip('0').rstrip('.') + 'M'
    if value >= 1e3: return '$' + f'{value / 1e3:,.0f}' + 'k'
    return '$' + f'{value:,.0f}'

def eligible(g):
    return bool(g.get('recommendation_eligible',g.get('on_sale') and g.get('value_per_dollar_now') is not None))

def metrics(g, tiers):
    probability=sum(1/t[2] for t in tiers if len(t)>2 and t[2] and t[2]>0 and t[1] is not None and t[1]>(g.get('ticket_price') or 0))
    return {'profit_odds':1/probability if probability and eligible(g) else None}

def ticket_row(g, tier_map, rank):
    gid=esc(g['game_no']); value=g.get('value_per_dollar_now'); profit=metrics(g,tier_map.get(str(g['game_no']),[]))['profit_odds']
    remaining=g.get('top_prizes_remaining'); total=g.get('top_prizes_total')
    dead=remaining==0 and bool(total)
    badge='<span class="status-badge depleted">Top prize gone</span>' if dead else '<span class="status-badge">Top prize available</span>'
    return f'''<tr data-game="{gid}"><td class="game-cell" data-label="Game"><span class="row-rank">{rank:02}</span><div><a href="/g/{gid}" data-open-game="{gid}">{esc(g['game_name'])}</a><span class="game-id">#{gid} · {badge}</span></div></td>
<td data-label="Ticket price"><strong>${g['ticket_price']:g}</strong></td><td data-label="Est. payout / $1"><strong class="ev-number">${value:.2f}</strong></td><td data-label="Profit odds">{'1 in '+f'{profit:.1f}' if profit else 'Not available'}</td><td data-label="Top prizes left"><strong>{remaining if remaining is not None else '—'}</strong><span class="secondary"> of {total if total else '—'}</span></td><td data-label="Top prize">{money(g.get('top_prize_value_num'))}</td><td class="row-actions"><button class="detail-button" type="button" data-open-game="{gid}" aria-label="Details for {esc(g['game_name'])}">Details <span aria-hidden="true">↗</span></button><label class="compare-check"><input type="checkbox" value="{gid}" data-compare aria-label="Compare {esc(g['game_name'])}"><span>Compare</span></label></td></tr>'''

def build_home(D):
    games=D['games']; tiers=D['tiers']; meta=D['meta']; built=meta['built']
    verified=[g for g in games if eligible(g)]
    ranked=sorted(verified,key=lambda g:(-(g.get('value_per_dollar_now') or 0),int(g['game_no'])))
    new=sorted(verified,key=lambda g:(g.get('launch_date') or '',g['game_no']),reverse=True)[:5]
    top=sorted(verified,key=lambda g:-(g.get('top_prize_value_num') or 0))
    top=[g for g in top if (g.get('top_prizes_remaining') or 0)>0][:3]
    depleted=[g for g in verified if g.get('top_prizes_total') and g.get('top_prizes_remaining')==0]
    byid={str(g['game_no']):g for g in games}
    winners=sorted([w for w in D.get('winners',[]) if w[1]],key=lambda w:w[1],reverse=True)[:6]
    items=D.get('deadlines',{}).get('items') or [dict(x,status='upcoming' if x.get('last_sell','')>=built else 'redeemable') for x in D.get('deadlines',{}).get('ending',[])]
    deadlines=[x for x in items if x.get('status')!='expired']
    def newcard(g):
        return f'''<a class="new-card" href="/g/{esc(g['game_no'])}" data-open-game="{esc(g['game_no'])}"><span class="price-tag">${g['ticket_price']:g}</span><span class="release-date">Released {esc(g.get('launch_date'))}</span><h3>{esc(g['game_name'])}</h3><div class="card-bottom"><span>{money(g.get('top_prize_value_num'))} top prize</span><strong>{g.get('top_prizes_remaining','—')} left ↗</strong></div></a>'''
    def claimcard(w):
        g=byid.get(str(w[0]),{})
        return f'''<li class="claim-item"><time datetime="{esc(w[1])}">{esc(w[1])}</time><div><strong>{money(w[6])} reported claimed</strong><a href="/g/{esc(w[0])}" data-open-game="{esc(w[0])}">{esc(g.get('game_name','Game #'+str(w[0])))}</a><span>{esc(w[3] or 'Florida')} · {esc(w[10] or 'Retailer not listed')}</span></div><span class="claim-dot" aria-hidden="true"></span></li>'''
    def deadline(x):
        sell=x.get('last_sell') or ''; redeem=x.get('last_redeem') or ''
        label='Sales end' if sell>=built else 'Sales ended'
        return f'''<li class="deadline-item"><div><a href="/g/{esc(x.get('id'))}">{esc(x.get('name'))}</a><span>{label} <time datetime="{esc(sell)}">{esc(sell or 'not announced')}</time></span></div><div><span>Redeem by</span><strong><time datetime="{esc(redeem)}">{esc(redeem or 'not announced')}</time></strong></div></li>'''
    schema={'@context':'https://schema.org','@graph':[
        {'@type':'WebSite','@id':SITE+'/#website','name':'Florida Scratch-Off Statistician','alternateName':'FL Scratch Stats','url':SITE+'/', 'inLanguage':'en-US'},
        {'@type':'WebPage','@id':SITE+'/#webpage','url':SITE+'/','name':'Florida Scratch-Off Odds & Prizes Remaining','dateModified':meta.get('built_at',built),'isPartOf':{'@id':SITE+'/#website'}},
        {'@type':'Dataset','name':'Florida Scratch-Off Game Statistics','description':'Official prize counts and published odds, with clearly labeled estimates of remaining-ticket payout. Independent analysis updated from Florida Lottery public data.','url':SITE+'/#tickets','dateModified':meta.get('built_at',built),'isAccessibleForFree':True,'creator':{'@type':'Organization','name':'Florida Scratch-Off Statistician'},'distribution':{'@type':'DataDownload','encodingFormat':'application/json','contentUrl':SITE+'/data.json'}}]}
    structured_json=json.dumps(schema,separators=(',',':')).replace('<','\\u003c')
    text=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#143d32">
<title>Florida Scratch-Off Odds & Prizes Remaining | FL Scratch Stats</title><meta name="description" content="Compare Florida scratch-off tickets by price, published odds, prizes remaining and estimated payout. New games, recent claims and deadlines, updated daily."><link rel="canonical" href="{SITE}/"><link rel="icon" href="/assets/flamingo.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css?v=2"><link rel="preload" href="/vendor/fonts/fraunces.woff2" as="font" type="font/woff2" crossorigin>
<meta property="og:type" content="website"><meta property="og:site_name" content="Florida Scratch-Off Statistician"><meta property="og:title" content="Know what’s left. Before you scratch."><meta property="og:description" content="Florida scratch-off odds, remaining prizes and independent comparisons. Updated daily. Free to use."><meta property="og:url" content="{SITE}/"><meta property="og:image" content="{SITE}/og-home.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="{SITE}/og-home.png"><script type="application/ld+json">{structured_json}</script>
<script src="/data.js" defer></script><script src="/assets/site.js?v=2" defer></script></head><body>
<a class="skip-link" href="#tickets">Skip to ticket comparisons</a><header class="site-header"><div class="header-inner"><a class="site-brand" href="/" aria-label="Florida Scratch-Off Statistician home"><img src="/assets/flamingo.svg" width="29" height="40" alt=""><span>Florida Scratch-Off <em>Statistician</em></span></a><nav class="site-nav" aria-label="Main navigation"><a href="#tickets">Compare tickets</a><a href="#new-games">New games</a><a href="#changes">Recent claims</a><a href="#deadlines">Deadlines</a><a href="#methodology">How it works</a></nav><a class="header-support" href="#support">Keep it independent <span aria-hidden="true">♡</span></a></div></header>
<main><section class="hero section-wrap" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow"><span class="live-dot"></span> Florida lottery data. Independent perspective.</p><h1 id="hero-title">Know what’s left.<br><em>Before you scratch.</em></h1><p class="hero-lede">Every Florida scratch-off, in one clear view. Compare published odds, see which prizes remain, and understand what the numbers actually mean.</p><div class="hero-actions"><a class="button primary" href="#tickets">Find a ticket by price <span aria-hidden="true">↓</span></a><a class="text-link" href="#methodology">The math, explained ↗</a></div><p class="hero-note">Free to explore. No sign-up. No winning promises.</p></div>
<aside class="snapshot" aria-label="Latest data snapshot"><div class="snapshot-title"><span class="eyebrow">The daily snapshot</span><span class="snapshot-mark" aria-hidden="true">✳</span></div><p class="snapshot-date">Updated <time id="data-date" datetime="{esc(meta.get('built_at',built))}">{esc(built)}</time><span id="freshness-note">Source snapshot</span></p><div class="snapshot-numbers"><div><strong>{len(verified)}</strong><span>games with verified comparisons</span></div><div><strong>{money(sum(g.get('value_remaining') or 0 for g in verified))}</strong><span>advertised prize value remaining</span></div><div><strong>{len(depleted)}</strong><span>games with no top prize left</span></div><div><strong>{len(new)}</strong><span>latest releases to explore</span></div></div><p class="snapshot-foot">From the Florida Lottery’s public records. Estimates are labeled, sources are linked.</p></aside></section>
<div class="trust-strip"><div class="section-wrap"><span>Official source data</span><span>Independent rankings</span><span>Privacy-friendly analytics</span><span>Updated daily</span></div></div>
<section class="section-wrap ticket-section" id="tickets" aria-labelledby="tickets-title"><div class="section-heading"><div><p class="eyebrow">The ticket explorer</p><h2 id="tickets-title">Find the numbers behind your ticket.</h2><p>Start with your price. Choose what matters. Compare the facts.</p></div><a class="utility-link" href="/games.csv" download>Download data ↓</a></div>
<div class="explorer"><form class="explorer-controls" id="ticket-filters" role="search"><div class="price-chooser"><span class="control-label" id="price-label">Ticket price</span><div class="price-chips" role="group" aria-labelledby="price-label"><a href="#tickets" data-price="all" class="price-chip active" aria-current="true">Any price</a>{''.join(f'<a class="price-chip" href="/florida-{price}-scratch-offs" data-price="{price}">${price}</a>' for price in PRICES)}</div></div><div class="filter-row"><label class="search-label"><span class="control-label">Search by game name or number</span><input id="game-search" name="q" type="search" placeholder="Try 500X or #1647" autocomplete="off"></label><label><span class="control-label">Compare by</span><select id="game-sort" name="sort"><option value="ev">Highest estimated payout</option><option value="jackpot">Largest remaining top prize</option><option value="profit">Best published profit odds</option><option value="new">Newest release</option></select></label><label class="top-prize-toggle"><input id="top-prize-only" type="checkbox"><span>Only games with a top prize left</span></label></div></form>
<div class="estimate-note"><span aria-hidden="true">ⓘ</span><p><strong>Estimated payout is not a prediction.</strong> $0.80 per $1 means a modeled average return of 80¢, not an 80% chance to win. Published profit odds are the chance of winning more than the ticket price. <a href="#methodology">Understand the assumptions.</a></p></div>
<div class="results-heading"><p id="results-count" aria-live="polite">Showing the first {min(12,len(ranked))} of {len(verified)} verified games</p><span id="sort-description">Sorted by estimated payout per $1</span></div>
<div class="ticket-table-wrap"><table class="ticket-table" id="ticket-table"><caption class="sr-only">Florida scratch-off ticket comparisons. Estimates use advertised prize values.</caption><thead><tr><th scope="col">Game</th><th scope="col">Price</th><th scope="col">Est. payout / $1</th><th scope="col">Profit odds</th><th scope="col">Top prizes left</th><th scope="col">Top prize</th><th scope="col"><span class="sr-only">Details and comparison</span></th></tr></thead><tbody id="ticket-results">{''.join(ticket_row(g,tiers,i+1) for i,g in enumerate(ranked[:12]))}</tbody></table></div><p class="empty-state" id="no-results" hidden>No matching games. Try a different price or search.</p><button class="button show-more" id="show-more" type="button">Show more games ↓</button><noscript><p class="noscript-note">Interactive filters need JavaScript. Use the price links above or the complete game directory below to explore every game.</p></noscript></div>
<section class="game-detail" id="game-detail" aria-label="Selected game details" hidden></section><section id="compare-panel" class="compare-panel" aria-label="Compare selected games" hidden></section>
<div class="method-line"><span>{len(games)-len(verified)} source-limited game{'' if len(games)-len(verified)==1 else 's'} excluded from recommendations.</span><a href="#methodology">Why we check data quality ↗</a><button type="button" id="print-guide" class="utility-link">Print this comparison ↗</button></div></section>
<section class="new-section" id="new-games" aria-labelledby="new-title"><div class="section-wrap"><div class="section-heading"><div><p class="eyebrow">Fresh from the source</p><h2 id="new-title">New Florida scratch-off games.</h2><p>Recent releases, with the same clear comparisons. New does not mean better odds.</p></div><a class="text-link" href="/new-florida-scratch-offs">All new games ↗</a></div><div class="new-grid">{''.join(newcard(g) for g in new)}</div></div></section>
<section class="section-wrap two-column" id="changes"><div><div class="section-heading"><div><p class="eyebrow">The prize notebook</p><h2>Recently reported claims.</h2><p>Claim dates and reported prize tiers from public winner reports.</p></div></div><ul class="claims-list">{''.join(claimcard(w) for w in winners)}</ul><p class="small-note">Reports may lag a claim. A recent winner does not make another ticket or retailer more likely to win.</p></div><aside class="jackpot-panel"><p class="eyebrow">Still in the prize table</p><h2>Big prizes, clear context.</h2>{''.join(f'<a class="jackpot-row" href="/g/{esc(g["game_no"])}" data-open-game="{esc(g["game_no"])}"><span><strong>{money(g.get("top_prize_value_num"))}</strong><span>{esc(g["game_name"])} <small>#{esc(g["game_no"])}</small></span></span><span>{g["top_prizes_remaining"]} of {g["top_prizes_total"]}<small>top prizes left</small></span></a>' for g in top)}<p>Remaining prizes are not a count of tickets waiting on a store shelf. Cash-option payouts may be lower than advertised values.</p></aside></section>
<section class="section-wrap deadlines-section" id="deadlines" aria-labelledby="deadlines-title"><div class="section-heading"><div><p class="eyebrow">Dates worth keeping</p><h2 id="deadlines-title">Sales endings & redemption deadlines.</h2><p>Sales end first. Winning tickets can remain redeemable until a later date.</p></div></div><ul class="deadline-list">{''.join(deadline(x) for x in deadlines) if deadlines else '<li class="empty-state">No upcoming deadlines were listed in the latest source snapshot.</li>'}</ul><p class="small-note">Verify deadlines with the <a href="https://floridalottery.com/games/scratch-offs" target="_blank" rel="noopener">Florida Lottery</a> before relying on a date.</p></section>
<section class="methodology-section" id="methodology" aria-labelledby="method-title"><div class="section-wrap two-column"><div><p class="eyebrow">Open numbers. No magic.</p><h2 id="method-title">Useful data.<br>Honest limits.</h2><p class="method-lede">This is an independent statistics project, not a system for finding winning tickets. Every ticket is independent. The house edge remains.</p><a class="text-link" href="/about">Full sources & methodology ↗</a><div class="source-card"><strong>Data you can inspect</strong><p>Florida Lottery game API, prize tiers and public winner reports. Updated automatically; suspect records are excluded from recommendations.</p><a href="/data.json" download>Download the full snapshot ↗</a></div></div><div class="faq-list"><details open><summary>What does “estimated payout” mean?</summary><p>Expected payout per dollar across a modeled remaining ticket pool. Unsold ticket counts are not public. We estimate inventory from the fraction of prizes unclaimed; this assumption can be wrong. A ticket returning less than $1 per $1 has a modeled loss.</p></details><details><summary>Are these the current odds of winning?</summary><p>Overall and profit odds come from the published prize structure. Estimated remaining-ticket payouts use unclaimed prize data, which can include already sold tickets awaiting a claim. They are different measurements and should not be treated as guaranteed current odds.</p></details><details><summary>Why do two tickets with the same name differ?</summary><p>Different game numbers identify different releases. Always match the game number on your ticket. Each release has its own prize counts, published odds and deadlines.</p></details><details><summary>Does a winning retailer improve my chances?</summary><p>Historical winner locations reflect sales volume and reporting, not a store being due for a win. We do not know a retailer’s current ticket inventory and do not recommend stores based on past winners.</p></details><details><summary>What happens when the data looks wrong?</summary><p>We reconcile advertised prize tiers with counts, label source limitations and exclude invalid odds records from recommendation lists. Source updates can lag. Always check the official game page before buying.</p></details><details><summary>How is this site funded?</summary><p>Optional Ko-fi support and clearly labeled sponsorships. Sponsors cannot buy a higher ticket ranking or change the calculations. Core comparisons are free. Cloudflare provides aggregate traffic and performance analytics.</p></details></div></div></section>
<section class="section-wrap support-section" id="support" aria-labelledby="support-title"><div class="section-heading"><div><p class="eyebrow">Independent, with your support</p><h2 id="support-title">Help keep the numbers open.</h2><p>No paywall on the facts. Support the work if you find it useful.</p></div></div><div class="support-grid"><article class="support-card"><span class="support-icon" aria-hidden="true">♡</span><h3>Buy the project a coffee.</h3><p>Help cover hosting, data checks and improvements. One-time support is welcome; there is no obligation to contribute.</p><a class="button primary" href="https://ko-fi.com/stuartmills" target="_blank" rel="noopener">Support on Ko-fi ↗</a><span class="small-note">Payments are handled by Ko-fi.</span></article><article class="sponsor-card"><span class="eyebrow">Sponsorship inquiries</span><h3>Support independent research.</h3><p>Interested in becoming the first sponsor? Tell us about your brand and the partnership you have in mind. Every placement will be labeled. Rankings stay independent.</p><details id="sponsor-form-details"><summary class="button secondary">Discuss a sponsorship →</summary><form id="sponsor-form" class="sponsor-form" method="post" action="/api/sponsorship"><noscript><p>This private inquiry form needs JavaScript. You can still support the project through the Ko-fi link.</p></noscript><fieldset id="sponsor-fields" disabled><div class="form-two"><label>Your name<input name="name" required minlength="2" maxlength="120" autocomplete="name"></label><label>Company or project<input name="company" required minlength="2" maxlength="160" autocomplete="organization"></label></div><label>Email for a reply<input type="email" name="email" required maxlength="254" autocomplete="email"></label><label>What do you have in mind?<textarea name="message" required minlength="20" maxlength="4000" rows="4"></textarea></label><label>Budget range <span class="optional">(optional)</span><input name="budget" maxlength="120"></label><label class="form-honeypot" aria-hidden="true">Leave this empty<input name="website" tabindex="-1" autocomplete="off"></label><label class="consent-label"><input type="checkbox" name="consent" required><span>You may contact me about this inquiry. My contact details and message will be stored privately for review, not published or added to a mailing list.</span></label><button class="button primary" type="submit">Send sponsorship inquiry →</button><p id="sponsor-status" role="status" aria-live="polite"></p></fieldset></form></details></article></div></section>
<section class="section-wrap browse-section"><details><summary>Browse every Florida scratch-off game</summary><ul class="game-directory">{''.join(f'<li><a href="/g/{esc(g["game_no"])}">{esc(g["game_name"])} <span>#{esc(g["game_no"])}</span></a></li>' for g in sorted(games,key=lambda g:g['game_name']))}</ul></details><div class="search-links"><span>Explore by price:</span>{''.join(f'<a href="/florida-{price}-scratch-offs">${price}</a>' for price in PRICES)}<a href="/best-value">Estimated payout ranking</a><a href="/florida-scratch-offs-most-prizes-left">Top prizes remaining</a></div></section>
</main><footer class="site-footer"><div class="section-wrap"><a class="site-brand" href="/">Florida Scratch-Off <em>Statistician</em></a><p>Independent. Not affiliated with or endorsed by the Florida Lottery or the State of Florida.</p><p>Figures change; verify with the official source. Advertised jackpots may differ from cash-option payouts. Nothing here changes your odds.</p><div class="footer-bottom"><span>18+ · Play responsibly. Only spend what you can afford to lose.</span><a href="/about">Sources & privacy</a><a href="#support">Support the project</a><span>Snapshot {esc(built)}</span></div></div></footer><div id="compare-tray" class="compare-tray" hidden><span id="compare-count">0 games selected</span><button id="compare-open" class="button primary" type="button">Compare selected</button><button id="compare-clear" class="icon-button" type="button" aria-label="Clear comparison">×</button></div><div id="site-status" class="sr-only" role="status" aria-live="polite"></div></body></html>'''
    (PUB/'index.html').write_text(text,encoding='utf-8')
    (PUB/'data.json').write_text(json.dumps(D,separators=(',',':')),encoding='utf-8')
    output=io.StringIO(); fields=['game_no','game_name','ticket_price','top_prize_display','top_prizes_remaining','top_prizes_total','overall_odds','value_per_dollar_now','launch_date','end_date','redemption_date','source_status']
    writer=csv.DictWriter(output,fieldnames=fields,extrasaction='ignore',lineterminator='\n'); writer.writeheader()
    for g in games: writer.writerow({k:g.get(k) for k in fields})
    (PUB/'games.csv').write_text(output.getvalue(),encoding='utf-8')
    return len(verified)

def build_site(D=None):
    if D is None:
        raw=(PUB/'data.js').read_text(encoding='utf-8').strip()
        D=json.loads(raw.removeprefix('const DATA=').removesuffix(';'))
        from pipeline.snapshot import repair_snapshot
        D=repair_snapshot(D)
        (PUB/'data.js').write_text('const DATA='+json.dumps(D,separators=(',',':'))+';',encoding='utf-8')
        from pipeline.refresh import write_stub_pages
        write_stub_pages(D)
    count=build_home(D)
    from pipeline.discovery import decorate_landing_pages
    decorate_landing_pages(PUB,D)
    print(f'Built HTML-first single-page home with {count} verified games and preserved search entry pages.')

if __name__=='__main__': build_site()
